<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { account } from '../accounts/auth'
import { currentTrack } from '../music/player/musicPlayer'
import { playTrack } from '../music/player/musicPlayer'
import { trackPayload } from '../music/musicLibrary'
import { request, socialEvent, failure } from './social'
const items = ref<any[]>([]), selected = ref<any>(null), friends = ref<any[]>([]), title = ref(''), members = ref<string[]>([])
const error = ref(''), busy = ref(false)
async function refresh() { items.value = (await request('/playlists')).items }
async function open(id: string) { try { selected.value = await request(`/playlists/${id}`) } catch (e) { error.value = failure(e) } }
async function create() { busy.value = true; error.value = ''; try { selected.value = await request('/playlists', 'POST', { title: title.value, members: members.value }); await refresh() } catch (e) { error.value = failure(e) } finally { busy.value = false } }
async function move(rawIndex: number | string, delta: number) { const index = Number(rawIndex); const order = selected.value.items.map((x: any) => x.id); const next = index + delta; if (next < 0 || next >= order.length) return; [order[index], order[next]] = [order[next], order[index]]; await edit({ order }) }
async function edit(body: any) { if (busy.value) return; busy.value = true; error.value = ''; try { selected.value = await request(`/playlists/${selected.value.id}`, 'PATCH', { revision: selected.value.revision, ...body }); await refresh() } catch (e) { error.value = failure(e); await open(selected.value.id) } finally { busy.value = false } }
watch(socialEvent, event => { if (event?.topic === 'shared_playlist' || event?.topic === 'reconnected') { void refresh().catch(() => {}); if (selected.value) void open(selected.value.id) } })
onMounted(async () => { try { await refresh(); friends.value = (await request('/relations')).items.filter((x: any) => x.user_id === account.value?.id && x.kind === 'friend' && x.status === 'accepted') } catch (e) { error.value = failure(e) } })
</script>
<template>
  <section class="social-stack"><div class="social-section-heading"><h2>共同歌单</h2><button v-if="selected" @click="selected = null">返回列表</button></div><p v-if="error" class="social-error" role="alert">{{ error }}</p><article v-if="selected" class="social-card"><h3>{{ selected.title }}</h3><p>{{ selected.members.map((x: any) => x.username).join('、') }} 共同整理</p><button :disabled="busy || !currentTrack" @click="edit({ track: trackPayload(currentTrack!) })">添加正在听的在线歌曲</button><ol class="social-queue"><li v-for="(item, index) in selected.items" :key="item.id"><span>{{ item.track_snapshot.title }} · {{ item.track_snapshot.artist }}</span><button @click="playTrack(item.track_snapshot)">播放</button><button :disabled="busy || index === 0" @click="move(index, -1)">上移</button><button :disabled="busy || index === selected.items.length - 1" @click="move(index, 1)">下移</button><button :disabled="busy" @click="edit({ remove_id: item.id })">移除</button></li></ol><details v-if="selected.owner_id === account?.id"><summary>管理成员</summary><div v-for="person in selected.members.filter((x: any) => x.user_id !== account?.id)" :key="person.user_id" class="social-row"><span>{{ person.username }}</span><button @click="edit({ member_id: person.user_id, remove_member: true })">移除</button></div><div v-for="friend in friends.filter(x => !selected.members.some((m: any) => m.user_id === x.target_user_id))" :key="friend.target_user_id" class="social-row"><span>{{ friend.username }}</span><button @click="edit({ member_id: friend.target_user_id })">加入歌单</button></div></details></article><template v-else><form class="social-card" @submit.prevent="create"><h3>和朋友一起整理</h3><label>歌单名称<input v-model="title" required maxlength="80" /></label><div class="social-actions"><label v-for="friend in friends" :key="friend.target_user_id" class="social-check"><input v-model="members" type="checkbox" :value="friend.target_user_id" />{{ friend.username }}</label></div><button class="primary" :disabled="busy || !title.trim()">创建共同歌单</button></form><div class="social-grid"><button v-for="item in items" :key="item.id" class="social-card" @click="open(item.id)"><h3>♫ {{ item.title }}</h3><small>共同编辑</small></button></div></template></section>
</template>
